    let s = slot != null ? slot : g.slots.indexOf(null);
    if (s < 0) return;
    if (g.slots[s] != null) g.pieces[g.slots[s]].used = false;
    g.slots[s] = p.i; p.used = true; this.sfx('drop'); this.up();
    if (p.say) this.play(p.say);
